 "content": "def transform(grid):
    """Extend the rectangle of 2s in each cardinal direction until blocked by a marker."""
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not cells:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    out = [row[:] for row in grid]

    # Extend each edge of the 2-rectangle along its rows/columns if no marker
    # (a nonzero color other than 2) lies in that outward ray.
    for r in range(r0, r1 + 1):
        if not any(grid[r][c] not in (0, 2) for c in range(c0)):
            for c in range(c0):
                out[r][c] = 2
        if not any(grid[r][c] not in (0, 2) for c in range(c1 + 1, w)):
            for c in range(c1 + 1, w):
                out[r][c] = 2
    for c in range(c0, c1 + 1):
        if not any(grid[r][c] not in (0, 2) for r in range(r0)):
            for r in range(r0):
                out[r][c] = 2
        if not any(grid[r][c] not in (0, 2) for r in range(r1 + 1, h)):
            for r in range(r1 + 1, h):
                out[r][c] = 2
    return out
